import json,sys
d=json.load(sys.stdin)
seen={}
def walk(node,parent=None):
    n=node.get('name'); st=node.get('process_status'); r=node.get('is_ready')
    if n and n not in seen: seen[n]=(st,r)
    for dep in (node.get('depends_on') or {}).values():
        walk(dep,n)
for k,v in d.get('nodes',{}).items(): walk(v)
from collections import Counter
print('total unique processes:',len(seen))
print(Counter(st for st,r in seen.values()))
print()
print('Non-running:')
for n,(st,r) in sorted(seen.items()):
    if st!='Running':
        print(f'  {n}: {st} ready={r}')
print()
print('Running but not Ready:')
for n,(st,r) in sorted(seen.items()):
